def comb_sort(nums):
    gap = len(nums)
    swap = True
    while gap > 1 or swap:
        if gap > 1:
            gap = max(1, gap // 2)
        swap = False
        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swap = True
    return nums
```

